actions.script:
const current = ec.service.sync().name('ironstone.ContactServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(ec.l10n.localize('This import is not available; start again from the file')); return }
if (!current.draft.options) { ec.message.addError(ec.l10n.localize('Choose the options first')); return }
ec.service.sync().name('ironstone.ContactServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'previewed'}}).call()

const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.ContactServices.get#ImportDraft').parameters({importId: importId}).call() || {}
hasDraft = !!current.found
previewRows = []
if (!hasDraft) return
draft = current.draft
const options = draft.options || {duplicatePolicy: 'skip'}
const out = ec.service.sync().name('mantle.party.ContactImportServices.preview#Contacts').parameters({fileLocation: current.fileLocation,
    fileName: draft.fileExt === 'vcf' ? 'source.vcf' : 'source.csv', presetId: draft.fileKind === 'csv' ? draft.presetId : null,
    columnMapping: draft.columnMapping || null, duplicatePolicy: options.duplicatePolicy || 'skip', maxRows: 200}).call()
if (ec.message.hasError()) { previewError = ec.message.getErrorsString(); ec.message.clearErrors(); hasDraft = false; return }
const actions = {create: L('Create'), update: L('Update'), skip: L('Skip')}
const reasons = {email: L('same email'), phone: L('same phone and name'), name: L('same name'), file: L('an earlier row')}
previewRows = Array.from(out.rowList || []).map((row) => ({rowNumber: row.rowNumber, name: row.name || L('(no name)'), action: row.action,
    actionLabel: actions[row.action] || row.action, actionStyle: row.action === 'create' ? 'text-positive' : (row.action === 'update' ? 'text-primary' : 'm-muted'),
    matchedPartyId: row.matchedPartyId || null, matchedText: row.matchedPartyId ? String(row.matchedName || row.matchedPseudoId || row.matchedPartyId) + ' · ' + (reasons[row.matchReason] || row.matchReason || '')
        : (row.matchedRowNumber ? ec.resource.expand('Row ${n} of the file', '', {n: row.matchedRowNumber}) : ''),
    problemText: Array.from(row.problems || []).join('; ')}))
counts = {rowCount: out.rowCount || 0, createCount: out.createCount || 0, updateCount: out.updateCount || 0, skipCount: out.skipCount || 0,
    problemCount: out.problemCount || 0}
summaryText = ec.resource.expand('${rows} rows: ${create} to create, ${update} to update, ${skip} to skip, ${problems} with problems', '',
        {rows: counts.rowCount, create: counts.createCount, update: counts.updateCount, skip: counts.skipCount, problems: counts.problemCount})
policyText = {skip: L('Duplicates are skipped'), update: L('Duplicates are updated'), create: L('Duplicates are created anyway')}[options.duplicatePolicy || 'skip']
moreRows = counts.rowCount > previewRows.length
